CREATE TABLE IF NOT EXISTS rumo10_universos (carreira_id BIGINT UNSIGNED PRIMARY KEY, estado_json JSON NOT NULL, atualizado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(carreira_id) REFERENCES rumo10_carreiras(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS rumo10_carreiras_arquivadas (carreira_id BIGINT UNSIGNED PRIMARY KEY, conta_id BIGINT UNSIGNED NOT NULL, arquivada_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(carreira_id) REFERENCES rumo10_carreiras(id) ON DELETE CASCADE, FOREIGN KEY(conta_id) REFERENCES rumo10_contas(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS rumo10_competicoes (codigo VARCHAR(30) PRIMARY KEY, nome VARCHAR(120) NOT NULL, edicao INT NOT NULL, formato VARCHAR(40) NOT NULL, dados_json JSON NOT NULL, fonte_url TEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS rumo10_clubes_oficiais (codigo VARCHAR(120) PRIMARY KEY, nome VARCHAR(120) NOT NULL, uf CHAR(2) NOT NULL, dados_json JSON NOT NULL, fonte_url TEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
ALTER TABLE rumo10_carreiras MODIFY conta_id BIGINT UNSIGNED NULL;
